<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/lib/SupportCallService.php';
$pdo = new PDO('sqlite::memory:', null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$pdo->exec('CREATE TABLE admin_users (admin_id TEXT PRIMARY KEY, display_name TEXT, role TEXT, enabled INTEGER, session_version INTEGER)');
$pdo->exec("INSERT INTO admin_users VALUES ('staff-one', 'Medewerker', 'staff', 1, 1), ('staff-two', 'Andere medewerker', 'staff', 1, 1), ('owner', 'Eigenaar', 'owner', 1, 1)");
$pdo->exec('CREATE TABLE account_profiles (account_id TEXT PRIMARY KEY, display_name TEXT, jid TEXT)');
$pdo->exec("INSERT INTO account_profiles VALUES ('tolk-one', 'Tolk', 'tolk@example.test'), ('tolk-two', 'Andere tolk', 'tolk2@example.test')");
$calls = new SupportCallService($pdo); $calls->ensureSchema();
$chat = new SupportChatService($pdo);
$regular = new InterpreterService($pdo);
foreach (['tolk-one', 'tolk-two'] as $account) $pdo->prepare("INSERT INTO interpreter_profiles VALUES (?, 'enabled', 1, ?)")->execute([$account, time()]);
$visitor = ['role' => 'visitor', 'id' => 'visitor-one'];
$staff = ['role' => 'staff', 'id' => 'staff-one', 'version' => 1];
$other = ['role' => 'staff', 'id' => 'staff-two', 'version' => 1];
$tolk = ['role' => 'interpreter', 'id' => 'tolk-one', 'version' => 1];
$tolk2 = ['role' => 'interpreter', 'id' => 'tolk-two', 'version' => 1];
$staffRow = $pdo->query("SELECT * FROM admin_users WHERE admin_id = 'staff-one'")->fetch(PDO::FETCH_ASSOC);
$checks = 0;
function checkCall(bool $value, string $label): void { global $checks; if (!$value) throw new RuntimeException($label); $checks++; }
function denyCall(callable $operation, int $status, string $label): void {
    try { $operation(); } catch (SupportChatFailure | InterpreterFailure $error) { checkCall($error->status === $status, $label . ': ' . $error->getMessage()); return; }
    throw new RuntimeException('Expected denial: ' . $label);
}
function act(array $actor, string $action, string $identifier, array $extra = []): array {
    global $calls;
    return $calls->action($actor, ['action' => $action, 'callId' => $identifier, 'clientId' => 'client-fixture-' . $actor['role']] + $extra);
}
$thread = $chat->visitorAction('visitor-one', '127.0.0.1', ['action' => 'start', 'name' => 'Bezoeker', 'acknowledged' => true])['threadId'];
denyCall(fn() => act($visitor, 'start', '', ['threadId' => $thread, 'mode' => 'rtt', 'consent' => true]), 409, 'No call before staff claim');
$chat->staffAction($staffRow, ['action' => 'claim', 'threadId' => $thread]);
denyCall(fn() => $calls->view($other, $thread, '', 'client-fixture-staff'), 403, 'Other staff cannot see call');
denyCall(fn() => $calls->view(['role' => 'visitor', 'id' => 'stranger'], $thread, '', 'client-fixture-visitor'), 404, 'Other visitor cannot see call');
denyCall(fn() => act($visitor, 'start', '', ['threadId' => $thread, 'mode' => 'rtt']), 400, 'Explicit call consent required');
$rtt = act($visitor, 'start', '', ['threadId' => $thread, 'mode' => 'rtt', 'consent' => true])['callId'];
checkCall($calls->view($staff, $thread, '', 'client-fixture-staff')['call']['mode'] === 'rtt', 'RTT invitation delivered');
denyCall(fn() => act($visitor, 'signal', $rtt, ['recipient' => 'staff', 'payload' => ['type' => 'offer', 'sdp' => 'v=0']]), 403, 'No signaling before both join');
denyCall(fn() => act($staff, 'join', $rtt), 400, 'Recipient must consent');
act($staff, 'join', $rtt, ['consent' => true]);
checkCall($calls->view($visitor, $thread, '', 'client-fixture-visitor')['call']['status'] === 'active', 'RTT active with both participants');
denyCall(fn() => act($visitor, 'request_interpreter', $rtt), 409, 'Signing interpreter requires TC');
act($visitor, 'signal', $rtt, ['recipient' => 'staff', 'payload' => ['type' => 'offer', 'sdp' => 'v=0']]);
checkCall(count($calls->view($staff, $thread, '', 'client-fixture-staff')['signals']) === 1, 'Authorized recipient receives signal');
checkCall($calls->view($staff, $thread, '', 'different-client-fixture')['signals'] === [], 'Second tab does not receive signaling');
denyCall(fn() => $calls->action($staff, ['action' => 'join', 'callId' => $rtt, 'clientId' => 'different-client-fixture', 'consent' => true]), 409, 'Second tab cannot silently take over');
denyCall(fn() => act($visitor, 'signal', $rtt, ['recipient' => 'staff', 'payload' => ['type' => 'rtt', 'text' => 'Private draft']]), 400, 'RTT is not stored in signaling API');
$tc = act($visitor, 'start', '', ['threadId' => $thread, 'mode' => 'tc', 'consent' => true])['callId'];
checkCall($calls->view($visitor, $thread, $rtt, 'client-fixture-visitor')['call']['status'] === 'ended', 'Upgrade ends only old RTT transport');
checkCall($chat->visitorView('visitor-one')['thread']['status'] === 'active', 'Chat survives call upgrade');
act($visitor, 'request_interpreter', $tc);
checkCall($calls->view($tolk, '', '', '')['queue'] === [], 'No interpreter queue before both join and permit');
act($staff, 'join', $tc, ['consent' => true]);
checkCall($calls->view($tolk, '', '', '')['queue'] === [], 'TC consent alone does not admit interpreter');
act($staff, 'allow_interpreter', $tc);
$queue = $calls->view($tolk, '', '', '')['queue'];
checkCall(count($queue) === 1 && array_keys($queue[0]) === ['call_id', 'created'], 'Interpreter queue contains no names or history');
denyCall(fn() => $calls->view($tolk, '', $tc, 'client-fixture-interpreter'), 403, 'Unassigned interpreter cannot inspect');
act($tolk, 'accept_interpreter', $tc);
denyCall(fn() => act($tolk2, 'accept_interpreter', $tc), 409, 'Only one interpreter can accept');
denyCall(fn() => $regular->action('tolk-one', ['action' => 'available', 'available' => true]), 409, 'Interpreter cannot become available in another queue');
denyCall(fn() => $regular->action('tolk-one', ['action' => 'request', 'provider' => 'internal', 'peer' => 'tolk2@example.test']), 409, 'Reservation prevents another Messenger interpreter room');
$view = $calls->view($tolk, '', $tc, 'client-fixture-interpreter');
checkCall(!isset($view['messages']) && !isset($view['thread']) && !isset($view['call']['visitor_id']), 'Interpreter has no support history or auth identities');
denyCall(fn() => act($visitor, 'signal', $tc, ['recipient' => 'interpreter', 'payload' => ['type' => 'offer', 'sdp' => 'v=0']]), 403, 'Interpreter must explicitly join');
act($tolk, 'join', $tc, ['consent' => true]);
act($visitor, 'signal', $tc, ['recipient' => 'interpreter', 'payload' => ['type' => 'offer', 'sdp' => 'v=0']]);
checkCall(count($calls->view($tolk, '', $tc, 'client-fixture-interpreter')['signals']) === 1, 'Joined interpreter gets only their signals');
act($visitor, 'cancel_interpreter', $tc);
checkCall($calls->view($visitor, $thread, '', 'client-fixture-visitor')['call']['status'] === 'active', 'Removing interpreter preserves original TC');
checkCall(count($calls->view($visitor, $thread, '', 'client-fixture-visitor')['members']) === 2, 'Interpreter removed from membership');
denyCall(fn() => $calls->view($tolk, '', $tc, 'client-fixture-interpreter'), 403, 'Removed interpreter loses access');
checkCall((int)$pdo->query('SELECT COUNT(*) FROM interpreter_reservations')->fetchColumn() === 0, 'Interpreter reservation released');
act($visitor, 'request_interpreter', $tc); act($staff, 'allow_interpreter', $tc);
$regular->action('tolk-one', ['action' => 'available', 'available' => true]);
act($tolk, 'accept_interpreter', $tc); act($tolk, 'join', $tc, ['consent' => true]);
$pdo->exec("UPDATE interpreter_profiles SET status = 'blocked' WHERE account_id = 'tolk-one'");
$view = $calls->view($visitor, $thread, '', 'client-fixture-visitor');
checkCall(!$view['call']['interpreterAssigned'] && $view['call']['status'] === 'active', 'Blocking interpreter removes only third leg');
denyCall(fn() => $calls->view($tolk, '', $tc, 'client-fixture-interpreter'), 403, 'Blocked interpreter cannot read');
$pdo->exec("UPDATE support_call_members SET seen = seen - 46 WHERE role = 'staff'");
checkCall($calls->view($visitor, $thread, '', 'client-fixture-visitor')['call'] === null, 'Stale original participant ends call');
checkCall($chat->visitorView('visitor-one')['thread']['status'] === 'active', 'Network timeout does not close text chat');
$tc = act($visitor, 'start', '', ['threadId' => $thread, 'mode' => 'tc', 'consent' => true])['callId'];
act($staff, 'join', $tc, ['consent' => true]);
$chat->staffAction($staffRow, ['action' => 'release', 'threadId' => $thread]);
checkCall($calls->view($visitor, $thread, '', 'client-fixture-visitor')['call'] === null, 'Releasing staff ends old media session');
checkCall((int)$pdo->query('SELECT COUNT(*) FROM support_call_signals')->fetchColumn() === 0, 'Ended call signaling purged');
$chat->staffAction($staffRow, ['action' => 'claim', 'threadId' => $thread]);
$tc = act($visitor, 'start', '', ['threadId' => $thread, 'mode' => 'tc', 'consent' => true])['callId'];
act($staff, 'join', $tc, ['consent' => true]);
act($visitor, 'signal', $tc, ['recipient' => 'staff', 'payload' => ['type' => 'offer', 'sdp' => 'v=0']]);
$otherRow = $pdo->query("SELECT * FROM admin_users WHERE admin_id = 'staff-two'")->fetch(PDO::FETCH_ASSOC);
$chat->staffAction($otherRow, ['action' => 'presence', 'available' => true]);
$chat->staffAction($staffRow, ['action' => 'transfer', 'threadId' => $thread, 'recipientId' => 'staff-two', 'recipientVersion' => 1, 'clientId' => 'fixture-transfer-call']);
checkCall($calls->view($visitor, $thread, '', 'client-fixture-visitor')['call'] === null, 'Transfer ends old media session rather than connecting new staff to it');
checkCall((int)$pdo->query('SELECT COUNT(*) FROM support_call_signals')->fetchColumn() === 0, 'Transfer clears old signaling');
denyCall(fn() => $calls->view($staff, $thread, '', 'client-fixture-staff'), 403, 'Transferred staff cannot access media');
$newRtt = act($visitor, 'start', '', ['threadId' => $thread, 'mode' => 'rtt', 'consent' => true])['callId'];
act($other, 'join', $newRtt, ['consent' => true]);
checkCall($calls->view($visitor, $thread, '', 'client-fixture-visitor')['call']['mode'] === 'rtt', 'New staff starts with RTT, not inherited camera consent');
checkCall((int)$pdo->query('SELECT COUNT(*) FROM account_profiles')->fetchColumn() === 2, 'No visitor or staff Messenger accounts created');
echo 'Support call service passed: ' . $checks . " checks; isolated SQLite, consent, RTT/TC, role isolation, interpreter reservation, revocation and cleanup.\n";
